import json
import time


class ExpiringCache:
    """Small JSON file cache whose entries expire after a fixed number of seconds."""

    def __init__(self, path, ttl_seconds=300):
        self.path = path
        self.ttl = ttl_seconds
        self.entries = {}

    def get(self, key):
        stored_at, value = self.entries.get(key, (0, None))
        return value if time.time() - stored_at <= self.ttl else None

    def put(self, key, value):
        self.entries[key] = (time.time(), value)
        with open(self.path, "w") as handle:
            json.dump(self.entries, handle)

