import time


class ResponseCache:
    """Expiry is lazy: a stale entry is dropped only when get() reads it, and nothing
    sweeps the cache in the background. ttl_seconds=None means entries never expire."""

    def __init__(self, ttl_seconds=None):
        self.ttl = ttl_seconds
        self._items = {}

    def set(self, url, body):
        self._items[url] = (time.time(), body)

    def get(self, url):
        stored_at, body = self._items.get(url, (0, None))
        if self.ttl is not None and time.time() - stored_at > self.ttl:
            self._items.pop(url, None)
            return None
        return body

