def read_batches(stream, batch_size=100):
    """Yield lists of up to batch_size lines from stream, stripping newlines.

    The final batch may be shorter."""
    batch = []
    for line in stream:
        batch.append(line.rstrip("\n"))
        if len(batch) == batch_size:
            yield batch
            batch = []
    if batch:
        yield batch

