from collections import deque


def tail_lines(stream, count):
    if count <= 0:
        return []
    return list(deque(stream, maxlen=count))

def complete_lines(read, chunk_size=4096):
    pending = ""
    while True:
        chunk = read(chunk_size)
        if not chunk:
            break
        pending += chunk
        *lines, pending = pending.split("\n")
        yield from lines
    if pending:
        yield pending

