def to_zone(moment, name):
    return moment.astimezone(ZoneInfo(name))


def test_spring_forward_skips_two_am():
    """The US spring-forward hour never appears: 07:00 UTC on 2024-03-10 becomes 03:00 EDT, with no 02:xx in between."""
    before = datetime(2024, 3, 10, 6, 59, tzinfo=timezone.utc)
    after = datetime(2024, 3, 10, 7, 0, tzinfo=timezone.utc)
    assert to_zone(before, "America/New_York").strftime("%H:%M %Z") == "01:59 EST"
    assert to_zone(after, "America/New_York").strftime("%H:%M %Z") == "03:00 EDT"

