import hashlib


def fingerprint(filters):
    return hashlib.sha1(repr(sorted(filters.items())).encode()).hexdigest()[:8]


class QueryCursor:
    """Binds a position to the filters that produced it.

    resume() raises ValueError when given different filters than the cursor was created with, because a position in one result set means nothing in another. Filters are compared by repr(), so 5 and "5" differ.
    """

    def __init__(self, position, filters):
        self.position = position
        self.fingerprint = fingerprint(filters)

    def resume(self, filters):
        if fingerprint(filters) != self.fingerprint:
            raise ValueError("cursor was issued for a different query")
        return self.position

