def push_with_retry(send, payload, retries=4):
    delay = 1.0
    for attempt in range(retries + 1):
        try:
            return send(payload)
        except TimeoutError:
            # Check before sleeping: the final failure must exit immediately, not after one more delay.
            if attempt == retries:
                print("giving up", file=sys.stderr)
                raise
            time.sleep(delay)
            delay = min(delay * 2, 30)

