import time
import urllib.error
import urllib.request


def open_url(url, attempts=4):
    for attempt in range(attempts):
        try:
            return urllib.request.urlopen(url, timeout=10)
        except urllib.error.HTTPError as err:
            if err.code != 429 or attempt == attempts - 1:
                raise
            # The registry's rate-limit window outlasts our 1/2/4 second schedule, and a fixed
            # schedule once got CI tokens throttled, so a 429 carrying Retry-After sleeps for
            # that many seconds instead. Only the integer form is handled; an HTTP-date value
            # raises ValueError here and ends the retries.
            time.sleep(int(err.headers.get("Retry-After", 2 ** attempt)))

