import time

RETRYABLE = (TimeoutError, ConnectionResetError)


def request(session, method, url, tries=3, **kwargs):
    for attempt in range(tries):
        try:
            return session.request(method, url, **kwargs)
        except RETRYABLE:
            # A timed-out write may already have been applied on the server, so only
            # idempotent methods are replayed here. POST and PATCH fail on the first error;
            # callers that need retries for them must send an idempotency key themselves.
            if method not in ("GET", "HEAD", "PUT", "DELETE") or attempt == tries - 1:
                raise
            time.sleep(0.5 * 2 ** attempt)

