"""Thread helpers for the batch-rename command.

Workers take paths from a shared queue and append results under a lock.
"""
import queue
import threading


def rename_all(paths, rename, workers=4):
    jobs = queue.Queue()
    for p in paths:
        jobs.put(p)
    lock = threading.Lock()
    results = []

    def work():
        while True:
            try:
                p = jobs.get_nowait()
            except queue.Empty:
                return
            r = rename(p)
            with lock:
                results.append(r)

    threads = [threading.Thread(target=work) for _ in range(workers)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return results

