import threading


def run_all(items, fn):
    results, errors = [], []
    lock = threading.Lock()

    def work(item):
        try:
            value = fn(item)
        except Exception as exc:
            with lock:
                errors.append(exc)
            return
        with lock:
            results.append((item, value))

    threads = [threading.Thread(target=work, args=(i,)) for i in items]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    if errors:
        raise errors[0]
    return results

