import unicodedata


class SearchKey:
    """Comparison key for matching typed queries against names.

    The key drops accents and compatibility forms such as ligatures, so it is
    lossy; never display it or write it back to the file.
    """

    def __init__(self, raw):
        decomposed = unicodedata.normalize("NFKD", raw.casefold())
        self.value = "".join(c for c in decomposed if not unicodedata.combining(c))

    def __eq__(self, other):
        return isinstance(other, SearchKey) and self.value == other.value

    def __hash__(self):
        return hash(self.value)

