import unicodedata


class FilenameNormalizer:
    """Rewrites filenames to NFC before they are compared or written.

    macOS directory listings have historically returned NFD names, so the same
    file showed up twice when a listing was merged with names typed on Linux.
    Every name entering the sync index passes through this class. Results are
    cached per instance, so changing form after the first call does not affect
    names already seen.
    """

    def __init__(self, form="NFC"):
        self.form = form
        self._seen = {}

    def __call__(self, name):
        try:
            return self._seen[name]
        except KeyError:
            fixed = unicodedata.normalize(self.form, name)
            self._seen[name] = fixed
            return fixed

