import unicodedata


class StrictNormalizer:
    """Normalizes to NFC and raises ValueError on lone surrogates.

    Lone surrogates would otherwise surface later as UnicodeEncodeError when
    the output file is written. Empty strings are returned as-is.
    """

    def __init__(self, encoding="utf-8"):
        self.encoding = encoding

    def __call__(self, text):
        if not text:
            return text
        result = unicodedata.normalize("NFC", text)
        try:
            result.encode(self.encoding)
        except UnicodeEncodeError as exc:
            raise ValueError(f"unencodable text: {text!r}") from exc
        return result

