class BatchAcker:
    """Buffers acknowledgements and sends them to the broker in groups.

    Nothing is sent until the buffer fills or flush() is called; messages
    still buffered at exit are redelivered by the broker.
    """

    def __init__(self, send, size=50):
        self._send, self._size, self._buf = send, size, []

    def ack(self, msg_id):
        self._buf.append(msg_id)
        if len(self._buf) >= self._size:
            self.flush()

    def flush(self):
        batch, self._buf = self._buf, []
        if batch:
            self._send(batch)

