import queue
import threading


class SocketPool:
    """Fixed-size socket pool; acquire() raises queue.Empty after the timeout.

    Sockets returned in a closed state are discarded, not replaced, so the pool shrinks.
    """

    def __init__(self, factory, size=3):
        self._factory = factory
        self._idle = queue.Queue()
        self._lock = threading.Lock()
        for _ in range(size):
            self._idle.put(factory())

    def acquire(self, timeout=2.0):
        return self._idle.get(timeout=timeout)

    def release(self, sock):
        if sock.fileno() == -1:
            return
        self._idle.put(sock)

