import threading


class BufferPool:
    """Recycles bytearray buffers of one fixed size.

    Buffers are not zeroed on release, so a recycled buffer still holds the previous
    contents. Callers must overwrite or slice to the number of bytes they actually read.
    Releasing a buffer of the wrong length raises ValueError rather than polluting the pool.
    """

    def __init__(self, buf_size=65536):
        self._buf_size = buf_size
        self._free = []
        self._lock = threading.Lock()

    def take(self):
        with self._lock:
            if self._free:
                return self._free.pop()
        return bytearray(self._buf_size)

    def give(self, buf):
        if len(buf) != self._buf_size:
            raise ValueError("buffer size mismatch")
        with self._lock:
            self._free.append(buf)

