import unicodedata


class EntrySorter:
    """Orders entries by Unicode code point after NFC normalization.

    Accented letters sort after all ASCII letters, which differs from what
    `sort` prints under most locales. Output is identical on every machine,
    so it is safe to compare against checked-in golden files.
    """

    def __init__(self, entries):
        self.entries = list(entries)

    def ordered(self):
        return sorted(self.entries, key=lambda e: unicodedata.normalize("NFC", e))

    def first(self):
        items = self.ordered()
        return items[0] if items else None

