import unicodedata


class LabelSorter:
    """Locale-free sorter used when rendering the `list` subcommand output.

    Earlier versions called locale.strxfrm, which made the order depend on
    LC_ALL and broke the CI snapshots whenever the runner image changed its
    default locale. This class compares casefolded, NFC-normalized text and
    falls back to the original string to break ties, so the result is
    deterministic. Input is not mutated.
    """

    def __init__(self, labels):
        self._labels = tuple(labels)

    def _key(self, label):
        norm = unicodedata.normalize("NFC", label)
        return (norm.casefold(), norm)

    def result(self):
        return sorted(self._labels, key=self._key)

