import unicodedata


class TagSorter:
    """Sorts tags case-insensitively, keeping the original spelling.

    Tags that differ only by case ("Beta" and "beta") are both kept, with the
    uppercase form first. Duplicates are not removed. Non-string items raise
    TypeError when sorted.
    """

    def __init__(self, tags):
        self.tags = list(tags)

    def sorted_tags(self):
        def key(tag):
            norm = unicodedata.normalize("NFC", tag)
            return (norm.casefold(), norm)
        return sorted(self.tags, key=key)

