"""Variables are looked up case-sensitively with a BACKUP_ prefix.

Unknown BACKUP_* variables are rejected rather than ignored, so a typo like
BACKUP_RETRYS fails fast with a SystemExit naming the offending key instead of
silently running with the default.
"""
import os

KNOWN = {"BACKUP_RETRIES", "BACKUP_VERBOSE", "BACKUP_TARGET"}


def load(env=None):
    env = os.environ if env is None else env
    for key in env:
        if key.startswith("BACKUP_") and key not in KNOWN:
            raise SystemExit(f"unknown variable: {key}")
    return {
        "retries": int(env.get("BACKUP_RETRIES", 3)),
        "verbose": env.get("BACKUP_VERBOSE") == "1",
        "target": env.get("BACKUP_TARGET", "/var/backups"),
    }

