import socket
import pytest


def probe(addr, timeout):
    s = socket.socket()
    s.settimeout(timeout)
    try:
        s.connect(addr)
        return s.recv(1)
    finally:
        s.close()


def test_probe_closes_socket_after_timeout(monkeypatch):
    """The socket is closed even when recv times out, so no descriptor leaks."""
    closed = []

    class FakeSocket:
        def settimeout(self, t): pass
        def connect(self, addr): pass
        def recv(self, n): raise socket.timeout()
        def close(self): closed.append(True)

    monkeypatch.setattr(socket, "socket", FakeSocket)
    with pytest.raises(socket.timeout):
        probe(("example.invalid", 80), 0.1)
    assert closed == [True]

