Early versions compared names case-sensitively, which produced separate
sections for "Work" and "work" in the same file. Names are now folded with
str.casefold() and surrounding whitespace is stripped before any lookup.
The on-disk config is not rewritten; legacy mixed-case headers are matched
through canonical() at read time, so never compare raw names directly.
"""


def canonical(name):
    return " ".join(name.split()).casefold()


def find_section(sections, name):
    wanted = canonical(name)
    for header in sections:
        if canonical(header) == wanted:
            return header
    return None

