class FrozenClock:
    """Returns a fixed timestamp and refuses to move backwards.

    Tests that need time to pass should call tick(); set() raises ValueError
    for earlier values, because the reminder scheduler assumes monotonic time.
    """

    def __init__(self, epoch):
        self._epoch = float(epoch)

    def time(self):
        return self._epoch

    def tick(self, seconds=1.0):
        self._epoch += seconds

    def set(self, epoch):
        if epoch < self._epoch:
            raise ValueError("clock cannot move backwards")
        self._epoch = float(epoch)

