import os
import stat


def can_write_report(path):
    """Return True if the report at path can be written by the current user.

    A missing file is judged by whether its parent directory is writable.
    """
    if os.path.exists(path):
        return os.access(path, os.W_OK)
    parent = os.path.dirname(os.path.abspath(path))
    mode = os.stat(parent).st_mode
    return bool(mode & stat.S_IWUSR) and os.access(parent, os.W_OK)

