import os


def check_readable(paths):
    """Raise PermissionError for the first unreadable path, before any is opened.

    The result is advisory: a file can still become unreadable between this check and the later open.
    """
    for p in paths:
        if not os.access(p, os.R_OK):
            raise PermissionError(f"cannot read {p}")
    return list(paths)

