import os
import stat


def private_key_ok(path):
    """Check that a key file is not accessible to group or others.

    Symlinks are followed. Returns False for any mode with group or other bits set,
    even read-only ones, mirroring the strictness of ssh.
    """
    try:
        mode = os.stat(path).st_mode
    except FileNotFoundError:
        return False
    return not (mode & (stat.S_IRWXG | stat.S_IRWXO))

