"""Incremental UTF-8 decoding of a log stream read in fixed-size chunks.

Reads binary input and prints text lines as they complete.
"""
import codecs
import sys


def decode_stream(stream, chunk_size=4096):
    decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
    pending = ""
    while True:
        chunk = stream.read(chunk_size)
        pending += decoder.decode(chunk, final=not chunk)
        *lines, pending = pending.split("\n")
        yield from lines
        if not chunk:
            break
    if pending:
        yield pending


if __name__ == "__main__":
    for line in decode_stream(sys.stdin.buffer):
        print(line)

