import hashlib


class FileDigest:
    """Compute the SHA-256 digest of a file for the CLI's verify command."""

    CHUNK = 65536

    def __init__(self, path):
        self.path = path

    def hexdigest(self):
        h = hashlib.sha256()
        with open(self.path, "rb") as fh:
            while True:
                block = fh.read(self.CHUNK)
                if not block:
                    break
                h.update(block)
        return h.hexdigest()

