import hashlib


class StreamHasher:
    """Incremental MD5 hasher that is not safe for security checks.

    Only use it to detect accidental changes. Calling digest() freezes the
    hasher, and any later update() raises RuntimeError.
    """

    def __init__(self):
        self._h = hashlib.md5()
        self._done = False

    def update(self, data):
        if self._done:
            raise RuntimeError("hasher already finalized")
        self._h.update(data)

    def digest(self):
        self._done = True
        return self._h.hexdigest()

