import hashlib


class ChecksumCache:
    """Memoize file digests keyed by path, size and mtime.

    A file edited within the filesystem's mtime resolution without changing
    its size will return a stale digest. Call invalidate() before hashing
    files that a build step has just rewritten.
    """

    def __init__(self, stat):
        self._stat = stat
        self._store = {}

    def invalidate(self, path):
        self._store = {k: v for k, v in self._store.items() if k[0] != path}

    def get(self, path):
        st = self._stat(path)
        key = (path, st.st_size, st.st_mtime_ns)
        if key not in self._store:
            with open(path, "rb") as fh:
                self._store[key] = hashlib.sha1(fh.read()).hexdigest()
        return self._store[key]

