class BatchedArgs:
    """Yields lists of at most size items; it is single-use and exhausted after one pass."""

    def __init__(self, source, size):
        self._source = iter(source)
        self._size = size

    def __iter__(self):
        return self

    def __next__(self):
        batch = []
        for item in self._source:
            batch.append(item)
            if len(batch) == self._size:
                break
        if not batch:
            raise StopIteration
        return batch

