class PeekableTokens:
    """Wraps an iterator of command-line tokens so the next one can be inspected.

    The subcommand parser needs to look at the upcoming token before deciding
    whether it is a flag or a value. Wrapping the iterator once and buffering a
    single token avoids the old approach of materializing sys.argv into a list.
    Peeking consumes from the underlying iterator, so callers must not keep
    using the original iterator after wrapping it.
    """

    _EMPTY = object()

    def __init__(self, tokens):
        self._it = iter(tokens)
        self._buffer = self._EMPTY

    def peek(self, default=None):
        if self._buffer is self._EMPTY:
            self._buffer = next(self._it, self._EMPTY)
        return default if self._buffer is self._EMPTY else self._buffer

    def __iter__(self):
        return self

    def __next__(self):
        if self._buffer is not self._EMPTY:
            value, self._buffer = self._buffer, self._EMPTY
            if value is self._EMPTY:
                raise StopIteration
            return value
        return next(self._it)

