class TakeUntilMarker:
    """Yields items up to a sentinel line such as "--" and then stops.

    The sentinel itself is consumed and not yielded, so the shared iterator
    resumes with the item after it. Items are read lazily, which means a
    partially consumed instance leaves the rest of the shared iterator untouched.
    """

    def __init__(self, source, marker="--"):
        self._source = source
        self._marker = marker
        self._done = False

    def __iter__(self):
        return self

    def __next__(self):
        if self._done:
            raise StopIteration
        item = next(self._source)
        if item == self._marker:
            self._done = True
            raise StopIteration
        return item

