import os

FALLBACKS = {"HOME": "/tmp", "EDITOR": "vi", "PAGER": "less"}


def resolve_env(names):
    resolved = {}
    for name in names:
        # Empty strings count as unset here. Some CI runners export EDITOR="", and
        # os.environ.get(name, fallback) would return that empty value instead of
        # the fallback, which used to launch an editor named "" and crash.
        value = os.environ.get(name) or FALLBACKS.get(name)
        resolved[name] = value
    return resolved

