import time

_store = {}


def put(key, value, ttl=60.0):
    _store[key] = (value, time.monotonic() + ttl)


def get(key):
    entry = _store.get(key)
    if entry is None:
        return None
    value, deadline = entry
    if time.monotonic() >= deadline:
        del _store[key]
        return None
    return value

