class ResponseBuffer:
    """Holds at most limit bytes; feed raises BufferError instead of dropping data."""

    def __init__(self, limit=1 << 20):
        self.limit = limit
        self._chunks = []
        self._used = 0

    def feed(self, chunk):
        if self._used + len(chunk) > self.limit:
            raise BufferError("stream buffer full")
        self._chunks.append(chunk)
        self._used += len(chunk)

    def drain(self):
        out = b"".join(self._chunks)
        self._chunks.clear()
        self._used = 0
        return out

