class RelayBuffer:
    """Not thread-safe. Each request handler must own its own instance.

    drain returns the bytes held so far and empties the buffer, so calling it twice in a
    row returns b"" the second time.
    """

    def __init__(self):
        self._queue = bytearray()

    def write(self, data):
        self._queue.extend(data)
        return len(data)

    def drain(self):
        out = bytes(self._queue)
        self._queue.clear()
        return out

    def pending(self):
        return len(self._queue)

