from zoneinfo import ZoneInfo


def to_user_timezone(utc_value, tz_name):
    """Convert a UTC datetime to the user's timezone and return it.

    Takes a timezone-aware or naive UTC datetime and an IANA timezone name
    such as "America/Toronto". Falls back to UTC if the name is unknown.
    """
    if utc_value.tzinfo is None:
        utc_value = utc_value.replace(tzinfo=ZoneInfo("UTC"))
    try:
