"""Cursor codec that binds a cursor to the sort order it was issued for.

Decoding raises ValueError if the cursor was created under a different sort
name, so a client cannot reuse a token after switching ordering. Malformed
input of any kind is reported the same way, which lets handlers map every
failure to a single 400 response.
"""
import base64
import json


def issue(sort_name, last_value):
    body = json.dumps({"s": sort_name, "v": last_value})
    return base64.urlsafe_b64encode(body.encode()).decode().rstrip("=")


def redeem(token, sort_name):
    try:
        padded = token + "=" * (-len(token) % 4)
        data = json.loads(base64.urlsafe_b64decode(padded))
        if data["s"] != sort_name:
            raise KeyError("sort mismatch")
        return data["v"]
    except Exception as exc:
        raise ValueError("invalid cursor") from exc

