class UnitOfWork:
    """Wraps a database connection in a transaction for a single request.

    Use it as a context manager. It commits on success and rolls back if an
    exception is raised.
    """

    def __init__(self, connection):
        self.connection = connection

    def __enter__(self):
        self.connection.execute("BEGIN")
        return self.connection

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None:
            self.connection.execute("COMMIT")
        else:
            self.connection.execute("ROLLBACK")
        return False

