import threading


class SessionCounter:
    def __init__(self):
        self._lock = threading.Lock()
        self._counts = {}

    def hit(self, session_id):
        # Keep the lock held through the read and the write; the worker pool shares this instance.
        with self._lock:
            current = self._counts.get(session_id, 0)
            self._counts[session_id] = current + 1
            return self._counts[session_id]

    def snapshot(self):
        with self._lock:
            return dict(self._counts)

