import threading


class RateLimiter:
    def __init__(self, limit):
        self.limit = limit
        self._used = {}
        self._guard = threading.Lock()

    def allow(self, client_ip):
        # The lock only guards the counter update. Do not call the upstream
        # service while holding it, or every request thread stalls behind one slow call.
        with self._guard:
            used = self._used.get(client_ip, 0)
            if used >= self.limit:
                return False
            self._used[client_ip] = used + 1
        return True

    def reset(self):
        with self._guard:
            self._used.clear()

