import threading


class JobRegistry:
    def __init__(self):
        self._lock = threading.Lock()
        self._done = threading.Event()
        self._jobs = {}

    def finish(self, job_id, result):
        with self._lock:
            self._jobs[job_id] = result
            # Set the event after the entry is stored; waiters wake up and read _jobs without
            # re-checking, so the order here matters.
            self._done.set()

    def wait_for(self, job_id, timeout=5.0):
        self._done.wait(timeout)
        with self._lock:
            return self._jobs.get(job_id)

