import os
import time


def purge_stale(directory, max_age_seconds):
    """Delete regular files older than max_age_seconds; subdirectories are left alone.

    Returns the number of files removed. Files that vanish mid-scan are ignored.
    """
    cutoff = time.time() - max_age_seconds
    removed = 0
    for entry in os.scandir(directory):
        if not entry.is_file(follow_symlinks=False):
            continue
        if entry.stat().st_mtime < cutoff:
            try:
                os.unlink(entry.path)
                removed += 1
            except FileNotFoundError:
                pass
    return removed

