import hmac


class RequestSigner:
    """Signs outgoing HTTP requests with an HMAC-SHA256 signature."""

    def __init__(self, key_id, secret):
        self.key_id = key_id
        self._secret = secret.encode()

    def sign(self, method, path, body=b""):
        digest = hashlib.sha256(body).hexdigest()
        message = "\n".join([method.upper(), path, digest]).encode()
        mac = hmac.new(self._secret, message, hashlib.sha256)
        return {"X-Key-Id": self.key_id, "X-Signature": mac.hexdigest()}

