"""Track in-flight offsets so a partition is committed only up to the first unfinished message.

Worker pools finish out of order, so acknowledging offset 7 before offset 5 is
done must not commit past 5. Not thread-safe; call from the consumer thread only.
"""


class OffsetTracker:
    def __init__(self):
        self.inflight = set()
        self.highest = -1

    def start(self, offset):
        self.inflight.add(offset)
        self.highest = max(self.highest, offset)

    def finish(self, offset):
        self.inflight.discard(offset)

    def safe_offset(self):
        return min(self.inflight) - 1 if self.inflight else self.highest

