import os


class ReportArchive:
    """Serves generated reports from a directory that deployment rotates via symlink.

    Releases are written to timestamped directories and a stable "current"
    link is swapped atomically. The link is resolved on every call rather
    than cached in __init__, so a rotation during a request is picked up by
    the next lookup. Files already opened keep reading the old release.
    """

    def __init__(self, current_link):
        self.current_link = current_link

    def open_report(self, name):
        release = os.path.realpath(self.current_link)
        return open(os.path.join(release, os.path.basename(name)), "rb")

