import asyncio


async def fetch_with_timeout(client, url, seconds):
    """Fetch a URL with a deadline, cancelling the request when it expires."""
    task = asyncio.ensure_future(client.get(url))
    try:
        return await asyncio.wait_for(task, timeout=seconds)
    except asyncio.TimeoutError:
        raise
    finally:
        if not task.done():
            task.cancel()

