import queue
import sqlite3

_FREE = queue.Queue()


def lease(path='app.db'):
    try:
        return _FREE.get_nowait()
    except queue.Empty:
        return sqlite3.connect(path, check_same_thread=False)


def release(conn):
    _FREE.put(conn)

