"""Worker pool for PDF rendering.

Rendering used to spawn a subprocess per request, which exhausted file descriptors under load. Helper processes are now started once at import time and handed out through a queue. The pool is sized to the gunicorn worker count, so a helper that is not checked back in within the request timeout starves every later request in that worker.
"""
import queue
import subprocess

_RENDERERS = queue.Queue()
for _ in range(4):
    _RENDERERS.put(subprocess.Popen(['cat'], stdin=subprocess.PIPE, stdout=subprocess.PIPE))


def checkout(timeout=5.0):
    return _RENDERERS.get(timeout=timeout)


def checkin(proc):
    _RENDERERS.put(proc)

