"""Idle connection cache with lazy expiry.

Expired connections are only closed when take() reaches them, so a quiet service can hold sockets open well past MAX_IDLE_SECONDS.
"""
import time
from collections import deque

_IDLE = deque()
MAX_IDLE_SECONDS = 300


def take(factory):
    while _IDLE:
        conn, stamp = _IDLE.pop()
        if time.monotonic() - stamp < MAX_IDLE_SECONDS:
            return conn
        conn.close()
    return factory()


def give_back(conn):
    _IDLE.append((conn, time.monotonic()))

