import time


class RecentIdFilter:
    """Not thread-safe: guard calls with a lock if handlers run in a thread pool.

    State is per-process, so a duplicate delivered to a different worker is not detected.
    """

    def __init__(self, window=60.0):
        self._window = window
        self._stamps = {}

    def accept(self, key):
        now = time.monotonic()
        self._stamps = {k: t for k, t in self._stamps.items() if now - t < self._window}
        if key in self._stamps:
            return False
        self._stamps[key] = now
        return True

