from collections import defaultdict


class SourceScopedDedup:
    """Tracks event ids separately for each upstream source.

    The same id arriving from two sources is delivered twice. Ids are never
    evicted; call forget() when a source disconnects or memory grows without bound.
    """

    def __init__(self):
        self._by_source = defaultdict(set)

    def claim(self, source, event_id):
        bucket = self._by_source[source]
        if event_id in bucket:
            return False
        bucket.add(event_id)
        return True

    def forget(self, source):
        self._by_source.pop(source, None)

