"""Locale-independent ordering for API results.

Keys never consult the process locale, so the order is identical on every
worker. Accents are stripped, which means "resume" and "résumé" compare
equal and fall back to the original input order (sorted is stable).
"""

import unicodedata


def fold(text):
    decomposed = unicodedata.normalize("NFD", text)
    base = [c for c in decomposed if not unicodedata.combining(c)]
    return "".join(base).casefold()


def order_labels(labels):
    return sorted(labels, key=fold)


def order_pairs(pairs):
    return sorted(pairs, key=lambda p: fold(p[0]))

