class BatchRunner:
    """Run a handler over items in fixed-size batches."""

    def __init__(self, handler, size=50):
        self.handler = handler
        self.size = size
        self.failed = []

    def run(self, items):
        results = []
        for start in range(0, len(items), self.size):
            batch = items[start:start + self.size]
            try:
                results.extend(self.handler(batch))
            except Exception as exc:
                self.failed.append((start, exc))
        return results

