class JobBatcher:
    """Collect jobs and flush them to a sink when the batch fills.

    Not thread-safe: each request handler must own its own instance. Jobs
    still pending are lost unless flush() is called before the object is
    discarded.
    """

    def __init__(self, sink, limit=100):
        self.sink = sink
        self.limit = limit
        self._pending = []

    def add(self, job):
        self._pending.append(job)
        if len(self._pending) >= self.limit:
            self.flush()

    def flush(self):
        if self._pending:
            self.sink(self._pending)
            self._pending = []

