class EmailBatchSender:
    """Send queued messages in groups, preserving order within a group.

    Messages for the same recipient are always placed in the same group, so
    group sizes may exceed max_group when one recipient has many messages.
    Delivery errors are recorded per recipient and do not stop later groups.
    """

    def __init__(self, transport, max_group=20):
        self.transport = transport
        self.max_group = max_group
        self.errors = {}

    def send_all(self, messages):
        by_rcpt = {}
        for msg in messages:
            by_rcpt.setdefault(msg["to"], []).append(msg)
        group = []
        for rcpt, msgs in by_rcpt.items():
            if group and len(group) + len(msgs) > self.max_group:
                self._send(group)
                group = []
            group.extend(msgs)
        if group:
            self._send(group)

    def _send(self, group):
        try:
            self.transport(group)
        except OSError as exc:
            for msg in group:
                self.errors[msg["to"]] = exc

