"""Flag registry that refuses unknown names.

is_on() raises KeyError for a flag that was never registered instead of
returning False, so a misspelled name fails loudly in tests rather than
silently disabling a feature in production. Flags are registered at import
time, and registering the same name twice raises ValueError.
"""

_REGISTRY = {}


def register(name, default):
    if name in _REGISTRY:
        raise ValueError(f"flag already registered: {name}")
    _REGISTRY[name] = default


def is_on(name, overrides=None):
    if overrides and name in overrides:
        return overrides[name]
    return _REGISTRY[name]

