"""Frozen-time utilities for scheduler tests.

The frozen clock never advances on its own, so any code that loops until a
deadline passes will hang. Call tick() explicitly to move time forward.
Timezone-aware datetimes only; naive values raise ValueError.
"""
from datetime import datetime, timedelta


class FrozenClock:
    def __init__(self, start: datetime):
        if start.tzinfo is None:
            raise ValueError("start must be timezone-aware")
        self._now = start

    def now(self) -> datetime:
        return self._now

    def tick(self, seconds: float) -> None:
        self._now += timedelta(seconds=seconds)

