class AccessPolicy:
    """Deny-by-default access check; unknown users and resources get False.

    Grants are read from the mapping passed in at construction, and the
    mapping is not copied, so later changes to it take effect immediately.
    """

    def __init__(self, acl):
        self._acl = acl

    def can(self, principal, verb, target):
        verbs = self._acl.get(target, {}).get(principal)
        if verbs is None:
            return False
        return verb in verbs or "*" in verbs

    def filter_visible(self, principal, targets):
        return [t for t in targets if self.can(principal, "read", t)]

