class RolePermissions:
    """Resolves permissions from role names carried in a session.

    This replaced the per-user grant table that the first version of the
    service used. Roles are expanded once in the constructor into a flat
    set of permission strings, so checks are a single set lookup, but that
    also means role definition changes only apply to new instances. The
    request middleware builds one instance per request for that reason.
    """

    def __init__(self, role_defs, roles):
        self._perms = set()
        for role in roles:
            self._perms |= set(role_defs.get(role, ()))

    def has(self, permission):
        return permission in self._perms

    def has_all(self, *permissions):
        return self._perms.issuperset(permissions)

