class TenantGuard:
    """Scopes every check to one tenant.

    A resource whose tenant differs from the guard's tenant is refused
    even for superusers, so cross-tenant access has to go through a
    separate guard built for the other tenant.
    """

    def __init__(self, tenant_id, superusers=()):
        self.tenant_id = tenant_id
        self._superusers = frozenset(superusers)

    def permits(self, user, resource):
        if resource["tenant_id"] != self.tenant_id:
            return False
        return user["id"] in self._superusers or user["id"] == resource["owner_id"]

