class SaturatingCounter:
    """Hit counter that clamps at its ceiling rather than raising.

    Once the ceiling is reached further increments are silently dropped, so a returned value equal to the ceiling means "at least this many", not an exact count.
    """

    def __init__(self, ceiling=65535):
        self.ceiling = ceiling
        self.count = 0

    def hit(self, n=1):
        self.count = min(self.ceiling, self.count + n)
        return self.count

