class OrderedChangeLog:
    """Collects profile changes and replays them in insertion order.

    Order matters because the audit exporter reads the same sequence that
    was applied, and an earlier version of the service used a plain set of
    pairs, which made replays nondeterministic across workers. Entries are
    kept as a list instead of a dict so repeated writes to one field remain
    visible in the history. replay() does not clear the log; call reset()
    once the changes have been persisted.
    """

    def __init__(self):
        self._entries = []

    def record(self, field, value):
        self._entries.append((field, value))

    def replay(self, profile):
        for field, value in self._entries:
            profile[field] = value
        return profile

    def reset(self):
        self._entries.clear()

