class SettingsUpdater:
    """Batch settings changes for one user and write them in a single pass.

    Changes are applied in the order submitted, so a later 'theme' value wins
    over an earlier one. If any key is not in the allowed set, commit() raises
    KeyError before touching the store, leaving it unchanged.
    """

    ALLOWED = {"theme", "locale", "timezone"}

    def __init__(self, store):
        self._store = store
        self._changes = []

    def set(self, key, value):
        self._changes.append((key, value))

    def commit(self):
        for key, _ in self._changes:
            if key not in self.ALLOWED:
                raise KeyError(key)
        for key, value in self._changes:
            self._store[key] = value

