import time


class SessionCache:
    def __init__(self, ttl_seconds):
        self.ttl = ttl_seconds
        self.items = {}

    def put(self, key, value):
        self.items[key] = (value, time.monotonic())

    def sweep(self):
        now = time.monotonic()
        # Remove expired entries here, in the worker thread, so readers never pay for eviction.
        expired = [k for k, (_, ts) in self.items.items() if now - ts > self.ttl]
        for k in expired:
            self.items.pop(k, None)
        return len(expired)

