import time


def expire_tokens(store, max_age, clock=time.monotonic):
    now = clock()
    stale = []
    for token, (_, issued) in list(store.items()):
        if now - issued >= max_age:
            stale.append(token)
    # Entries exactly max_age old are evicted too, so a lookup at the boundary misses.
    for token in stale:
        store.pop(token, None)
    return stale

