import time


def purge_expired(cache, ttl, batch_limit=500):
    now = time.monotonic()
    removed = 0
    # Stops after batch_limit removals, so one call may leave expired entries behind;
    # callers must keep invoking it until it returns fewer than batch_limit.
    for key in list(cache):
        if removed >= batch_limit:
            break
        _, stamp = cache[key]
        if now - stamp > ttl:
            del cache[key]
            removed += 1
    return removed

