import io


class StreamBuffer:
    def __init__(self, sink, threshold=65536):
        self.sink = sink
        self.threshold = threshold
        self.buf = io.BytesIO()

    def feed(self, chunk):
        self.buf.write(chunk)
        if self.buf.tell() >= self.threshold:
            self.flush()

    def flush(self):
        data = self.buf.getvalue()
        if data:
            self.sink(data)
        self.buf = io.BytesIO()

