"""Line-oriented stream buffer for the worker.

The sink only ever receives complete lines; a trailing partial line stays buffered
until more data arrives or close() is called, so a stream without a final newline
loses nothing only if close() runs.
"""


class LineBuffer:
    def __init__(self, sink):
        self.sink = sink
        self.pending = b""

    def feed(self, chunk):
        self.pending += chunk
        *lines, self.pending = self.pending.split(b"\n")
        for line in lines:
            self.sink(line)

    def close(self):
        if self.pending:
            self.sink(self.pending)
            self.pending = b""

