"""Chunk coalescing buffer for worker output streams.

Not thread-safe: each worker owns its own instance. Memoryview slices returned by
drain() alias the internal bytearray and become invalid after the next append(), so
consumers must copy them if they need to keep the data.
"""


class Coalescer:
    def __init__(self, min_size=4096):
        self.min_size = min_size
        self.data = bytearray()

    def append(self, chunk):
        self.data.extend(chunk)

    def ready(self):
        return len(self.data) >= self.min_size

    def drain(self):
        view = memoryview(self.data)[: len(self.data)]
        return view

