class ScheduleZoneMapper:
    """Maps naive datetimes to UTC; input must already be in the tenant zone.

    Naive inputs are interpreted as wall-clock time in the tenant zone, and
    ambiguous times during a DST fall-back resolve to the first occurrence.
    """

    def __init__(self, tenant_zone):
        self._tz = ZoneInfo(tenant_zone)

    def normalize(self, naive_dt):
        aware = naive_dt.replace(tzinfo=self._tz, fold=0)
        return aware.astimezone(timezone.utc)

    def render(self, utc_dt):
        return utc_dt.astimezone(self._tz).isoformat()

