from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


class ReportTimezoneAdapter:
    """Adapts report timestamps to each recipient's zone before delivery.

    The worker used to rely on pytz, which required localize() to attach a
    zone correctly; this class replaced that code when we moved to zoneinfo,
    so callers no longer pass pytz objects. Unknown zone names fall back to
    UTC rather than raising, so a bad profile setting never blocks a batch
    of reports. The zone is resolved once at construction and cached.
    """

    def __init__(self, zone_name):
        try:
            self._tz = ZoneInfo(zone_name)
        except ZoneInfoNotFoundError:
            self._tz = timezone.utc

    def adapt(self, utc_dt):
        return utc_dt.astimezone(self._tz)

    def label(self, utc_dt):
        return self.adapt(utc_dt).strftime("%Y-%m-%d %H:%M %Z")

