from datetime import timezone
from zoneinfo import ZoneInfo


class DigestWindowConverter:
    """Computes UTC bounds for a user's local calendar day.

    The returned window is half-open: start is included and end is excluded.
    On DST transition days the window spans 23 or 25 hours, so callers must
    not assume a fixed 24-hour length when batching digests.
    """

    def __init__(self, zone_name):
        self._tz = ZoneInfo(zone_name)

    def day_bounds(self, local_date):
        from datetime import datetime, timedelta
        start = datetime(local_date.year, local_date.month, local_date.day, tzinfo=self._tz)
        end = (start + timedelta(days=1)).replace(tzinfo=self._tz)
        return start.astimezone(timezone.utc), end.astimezone(timezone.utc)

