import base64
import json


def next_page(fetch, cursor_token, page_size=100):
    # Tokens come from clients and are untrusted: a malformed one must be
    # treated as a restart from the beginning, never as an error, so the
    # worker does not crash-loop on a single bad queued job.
    try:
        state = json.loads(base64.urlsafe_b64decode(cursor_token))
    except (TypeError, ValueError):
        state = {"after_id": 0}
    rows = fetch(after_id=state["after_id"], limit=page_size)
    if not rows:
        return [], None
    next_token = base64.urlsafe_b64encode(json.dumps({"after_id": rows[-1]["id"]}).encode())
    return rows, next_token.decode()

