import random
import time


def deliver_with_backoff(send, payload, attempts=6, base=1.0, cap=60.0):
    """Send payload, backing off exponentially between failed attempts.

    The cap exists because the upstream webhook gateway drops connections
    that stay queued longer than about a minute, and earlier versions of
    the worker doubled delays without limit and stalled whole queues. Each
    delay is the capped exponential value plus up to 10 percent jitter.
    Only ConnectionError and TimeoutError are retried; anything else
    propagates immediately.
    """
    for n in range(attempts):
        try:
            return send(payload)
        except (ConnectionError, TimeoutError):
            if n == attempts - 1:
                raise
            delay = min(cap, base * 2 ** n)
            time.sleep(delay * (1 + random.random() * 0.1))

