class PayloadRedactor:
    """Returns a redacted deep copy of a job payload; the input is never mutated.

    Keys are matched case-insensitively at any nesting depth, including inside
    lists. Values under a matching key are replaced wholesale, so a nested dict
    under "credentials" is masked as a single string.
    """

    def __init__(self, keys=("password", "credentials", "api_key")):
        self.keys = {k.lower() for k in keys}

    def redact(self, value):
        if isinstance(value, dict):
            return {
                k: "***" if k.lower() in self.keys else self.redact(v)
                for k, v in value.items()
            }
        if isinstance(value, list):
            return [self.redact(v) for v in value]
        return value

