def check_message(msg, required):
    """Return problems found in msg; never raises on malformed input.

    Unknown keys are ignored, and bool is rejected where int is required.
    """
    problems = []
    for key, typ in required.items():
        value = msg.get(key) if isinstance(msg, dict) else None
        if value is None:
            problems.append(f"{key}: missing")
        elif typ is int and isinstance(value, bool):
            problems.append(f"{key}: bool not allowed")
        elif not isinstance(value, typ):
            problems.append(f"{key}: expected {typ.__name__}")
    return problems

