def validate_task_record(record, spec, strict=False):
    """Check a task record against spec inside the worker loop.

    The worker used to let validation exceptions escape, which killed the
    consumer thread and stalled the whole queue. This function now returns
    error strings instead, so the caller decides whether to dead-letter the
    task. With strict=True, keys absent from spec are reported as errors too.
    """
    errors = []
    for name, typ in spec.items():
        if name not in record:
            errors.append(f"{name} is required")
        elif not isinstance(record[name], typ):
            errors.append(f"{name} must be {typ.__name__}")
    if strict:
        errors.extend(f"unexpected key {k}" for k in record if k not in spec)
    return errors

