import queue
import threading


class BufferPool:
    def __init__(self, buf_size=65536, max_buffers=8):
        self._buf_size = buf_size
        self._free = queue.LifoQueue(maxsize=max_buffers)
        self._stop = threading.Event()

    def get(self):
        try:
            return self._free.get_nowait()
        except queue.Empty:
            return bytearray(self._buf_size)

    def put(self, buf):
        if self._stop.is_set():
            return
        # Callers may still hold slices of buf; zeroing here would corrupt
        # data that a downstream consumer has not read yet.
        try:
            self._free.put_nowait(buf)
        except queue.Full:
            pass

    def close(self):
        self._stop.set()

