import sqlite3
import threading


class SqlitePool:
    def __init__(self, path, size=3):
        self._path = path
        self._conns = queue.Queue()
        self._owner = threading.get_ident()
        for _ in range(size):
            # sqlite3 refuses cross-thread use by default. The pool hands
            # connections to other worker threads, so the check must be off,
            # which makes callers responsible for never sharing one
            # connection between two threads at the same time. The queue
            # guarantees exclusivity as long as every acquire is paired
            # with a release, so leaked connections shrink the pool for good.
            self._conns.put(sqlite3.connect(path, check_same_thread=False))

    def acquire(self, timeout=None):
        return self._conns.get(timeout=timeout)

    def release(self, conn):
        self._conns.put(conn)

