import queue
import time


class SessionPool:
    def __init__(self, open_session, max_age=300.0):
        self._open = open_session
        self._max_age = max_age
        self._idle = queue.LifoQueue()

    def checkout(self):
        while True:
            try:
                session, born = self._idle.get_nowait()
            except queue.Empty:
                return self._open(), time.monotonic()
            # Expiry is judged by creation time, not last use, because the
            # server revokes tokens a fixed time after login even if the
            # session stays busy.
            if time.monotonic() - born < self._max_age:
