def build_retry_policy(job_options, worker_config):
    """Combine per-job and worker-wide retry settings.

    Per-job values override the worker config key by key, not as a whole
    dict, so a job that sets only max_attempts still inherits the worker's
    backoff. A job value of None means inherit; use 0 to disable retries.
    The returned dict is a copy and safe to mutate.
    """
    policy = {"max_attempts": 3, "backoff": 1.5}
    policy.update(worker_config.get("retry", {}))
    for key, value in job_options.items():
        if value is not None:
            policy[key] = value
    return policy

