"""Retry-aware batch processing for the email worker.

The sink callback must be idempotent. A batch whose callback raises is
retried up to MAX_TRIES times with the same contents, so recipients could
receive duplicates if the sink partially succeeded before failing. After the
last failure the batch is dropped and counted in `dropped`.
"""
import threading

MAX_TRIES = 3
dropped = 0


def process(batches, sink):
    global dropped
    for batch in batches:
        for attempt in range(MAX_TRIES):
            try:
                sink(batch)
                break
            except Exception:
                if attempt == MAX_TRIES - 1:
                    dropped += 1


def start(batches, sink):
    t = threading.Thread(target=process, args=(batches, sink), daemon=True)
    t.start()
    return t

