import socket


class PollingReader:
    """Reads from a socket in short slices so the worker can notice a stop request.

    Not thread-safe: the timeout is set on the shared socket, so any other thread
    using it will see the slice timeout. recv_chunk() returns b"" on a timeout,
    which is distinct from the peer closing the connection (that raises ConnectionError).
    """

    def __init__(self, sock, stop_event, slice_seconds=0.5):
        self.sock = sock
        self.stop_event = stop_event
        self.slice_seconds = slice_seconds

    def recv_chunk(self, n=4096):
        self.sock.settimeout(self.slice_seconds)
        try:
            data = self.sock.recv(n)
        except socket.timeout:
            return b""
        if not data:
            raise ConnectionError("peer closed")
        return data

