import threading


class WorkerThreadGuard:
    """Fails a test if it leaves worker threads running after teardown.

    Only threads started while the guard is active are checked, and it waits at most one second
    for each before raising AssertionError.
    """

    def __enter__(self):
        self._before = set(threading.enumerate())
        return self

    def __exit__(self, *exc):
        for t in set(threading.enumerate()) - self._before:
            t.join(timeout=1.0)
            if t.is_alive():
                raise AssertionError("leaked thread: %s" % t.name)
        return False

