import subprocess


class ProcessReaper:
    """Terminates tracked children at shutdown, escalating to SIGKILL after grace seconds.

    Only the direct child is signalled; grandchildren it spawned keep running.
    """

    def __init__(self, grace=5.0):
        self.grace = grace
        self.children = []

    def spawn(self, argv):
        proc = subprocess.Popen(argv)
        self.children.append(proc)
        return proc

    def shutdown(self):
        for proc in self.children:
            proc.terminate()
            try:
                proc.wait(self.grace)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()

