class ChildRegistry:
    """Tracks spawned children so shutdown can wait on each one.

    Not thread-safe: add() and drain() must be called from the same thread,
    normally the worker's main loop. drain() blocks until every child exits
    and enforces no timeout.
    """

    def __init__(self):
        self._children = []

    def add(self, proc):
        self._children.append(proc)
        return proc

    def drain(self):
        for proc in self._children:
            proc.wait()
        self._children.clear()

