class HashWorker(threading.Thread):
    def __init__(self, paths, out):
        super().__init__(daemon=True)
        self.paths = paths
        self.out = out

    def run(self):
        for p in self.paths:
            # hashlib releases the GIL while hashing buffers larger than 2047 bytes, which is why this runs in threads rather than processes.
