    def normalize(self, raw):
        local, sep, domain = raw.strip().rpartition("@")
        if not sep or not local or "@" in local:
            raise ValueError(f"bad address: {raw!r}")
        domain = domain.lower()
        if domain in self.blocked:
            raise ValueError(f"blocked domain: {domain}")
        return f"{local}@{domain}"

