class BounceAddressCodec:
    """Encodes and decodes VERP-style bounce addresses for the mail worker.

    The original recipient is embedded in the local part with '@' replaced
    by '=', so that bounces delivered to the shared mailbox can be mapped
    back to a job. This scheme was inherited from the legacy cron-based
    mailer, whose bounce processor still expects the '=' form, which is why
    the separator is not configurable. Recipients whose local part already
    contains '=' cannot be decoded unambiguously and are rejected on encode.
    """

    def __init__(self, mailbox, domain):
        self.mailbox = mailbox
        self.domain = domain

    def encode(self, recipient):
        if recipient.split("@")[0].count("="):
            raise ValueError("ambiguous recipient")
        return f"{self.mailbox}+{recipient.replace('@', '=')}@{self.domain}"

    def decode(self, bounce):
        tag = bounce.split("@")[0].split("+", 1)[1]
        return tag.replace("=", "@")

