class AddressDeduper:
    """Drops duplicate recipients while preserving first-seen order.

    Comparison is case-insensitive on the whole address, but the first
    spelling encountered is the one returned. Instances are stateful: reuse
    one across batches only if duplicates across batches should also be
    dropped; call reset() between unrelated jobs. Not safe to share between
    threads without external locking.
    """

    def __init__(self):
        self._seen = set()

    def filter(self, addresses):
        out = []
        for addr in addresses:
            key = addr.strip().lower()
            if key not in self._seen:
                self._seen.add(key)
                out.append(addr.strip())
        return out

    def reset(self):
        self._seen.clear()

