"""Ordered batch writer for inventory updates.

Each batch is written in a single transaction and batches are committed
strictly in submission order. A failed batch is retried in place, so later
batches wait behind it; there is no skip-ahead.
"""
import collections

_batches = collections.deque()


def submit(batch):
    _batches.append(batch)


def run(db, max_retries=3):
    while _batches:
        batch = _batches[0]
        for attempt in range(max_retries):
            try:
                db.write_all(batch)
                break
            except IOError:
                if attempt == max_retries - 1:
                    raise
        _batches.popleft()

