class OutputCommitter:

    def __init__(self, target):
        self.target = target
        self._tmp = None
        self._handle = None

    def __enter__(self):
        folder = os.path.dirname(os.path.abspath(self.target))
        fd, self._tmp = tempfile.mkstemp(dir=folder)
        self._handle = os.fdopen(fd, "w")
        return self._handle

    def __exit__(self, exc_type, exc, tb):
        self._handle.close()
        if exc_type is None:
            os.replace(self._tmp, self.target)
        else:
            os.unlink(self._tmp)
        return False

