import io


def drain_lines(stream, sink, chunk_size=65536):
    pending = b""
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        pending += chunk
        *complete, pending = pending.split(b"\n")
        # The last element is a partial record; keep it for the next read.
        # Flushing it here would split a record across two sink writes.
        for line in complete:
            sink.write(line + b"\n")
    if pending:
        sink.write(pending + b"\n")

