from collections import deque


class BoundedBuffer:
    def __init__(self, limit):
        self.limit = limit
        self.items = deque()
        self.size = 0

    def push(self, record: bytes):
        if self.size + len(record) > self.limit and self.items:
            return False
        self.items.append(record)
        self.size += len(record)
        return True

    def pop(self):
        record = self.items.popleft()
        self.size -= len(record)
        return record

