def partition_key(local_ts: datetime, zone_name: str) -> str:
    aware = local_ts.replace(tzinfo=ZoneInfo(zone_name), microsecond=0)
    utc = aware.astimezone(timezone.utc)
    return utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def partition_keys(stamps, zone_name):
    return sorted({partition_key(s, zone_name) for s in stamps})

