import random


class FullJitterBackoff:
    """Attempt numbers are zero-based; delay(0) is the wait before the first retry.

    Delays are drawn uniformly from [0, ceiling], so a single delay can be
    near zero. Do not use the value as a minimum spacing guarantee.
    """

    def __init__(self, base=1.0, cap=60.0):
        self.base = base
        self.cap = cap

    def delay(self, attempt: int) -> float:
        ceiling = min(self.cap, self.base * (2 ** attempt))
        return random.uniform(0, ceiling)

    def sleep_times(self, n: int) -> list[float]:
        return [self.delay(i) for i in range(n)]

