class RetryBudget:

    def __init__(self, budget_seconds=120.0, base=2.0):
        self.budget = budget_seconds
        self.base = base
        self.spent = 0.0
        self.attempt = 0

    def allow(self) -> bool:
        return self.spent + self._next() <= self.budget

    def _next(self) -> float:
        return self.base * 2 ** self.attempt

    def consume(self) -> float:
        wait = self._next()
        self.spent += wait
        self.attempt += 1
        return wait

