class EventSchema:
    """Checks event dicts before they enter the ingest queue.

    Originally this lived inside the loader, but the loader and the
    replay tool both needed identical rules, so it was split out. Types
    are compared with isinstance, so bool passes as int; the ingest
    stage relies on this because upstream emits 0/1 flags as ints and
    True/False interchangeably. Fields are checked in schema order and
    the first failure is returned as a single message.
    """

    def __init__(self, fields):
        self.fields = fields

    def first_error(self, event):
        for name, kind in self.fields:
            if name not in event:
                return f"{name} missing"
            if not isinstance(event[name], kind):
                return f"{name} wrong type"
        return None

