class PayloadGuard:
    """Schema check that mutates nothing but is order-sensitive.

    Fields are a list of (name, type, nullable) tuples. A nullable field
    may be absent or None; a non-nullable field must be present and
    non-None. Nested dicts are not descended into, so callers must
    build a separate guard for each nested level.
    """

    def __init__(self, fields):
        self.fields = fields

    def ok(self, payload):
        for name, kind, nullable in self.fields:
            value = payload.get(name)
            if value is None:
                if not nullable:
                    return False
            elif not isinstance(value, kind):
                return False
        return True

