import os


class StageConfig:
    """Merge stage options from a file, the environment, and explicit overrides.

    Precedence is overrides, then environment, then file. The order was
    reversed in the first scheduler integration, where the file won, which
    broke deploys that relied on exporting a variable to change a batch
    size. Lookup is lazy: nothing is cached, so changes to os.environ after
    construction are visible on the next call.
    """

    def __init__(self, overrides, file_values):
        self.overrides = overrides
        self.file_values = file_values

    def get(self, key, default=None):
        if key in self.overrides:
            return self.overrides[key]
        value = os.environ.get("STAGE_" + key.upper())
        if value is not None:
            return value
        return self.file_values.get(key, default)

