import struct

MAGIC = b"\xd3\x7a"


def read_frame(buf, offset=0):
    if len(buf) - offset < 6:
        return None
    if buf[offset:offset + 2] != MAGIC:
        raise ValueError("bad frame marker")
    (size,) = struct.unpack_from(">I", buf, offset + 2)
    end = offset + 6 + size
    if len(buf) < end:
        return None
    return bytes(buf[offset + 6:end]), end

