def open_stream(path, mode="rb"):
    for suffix, opener in CODECS.items():
        if path.endswith(suffix):
            return opener(path, mode)
    return open(path, mode)


def read_lines(path):
    with open_stream(path) as fh:
        for line in fh:
            yield line.rstrip(b"\n")

