"""Streaming compression for partner export files.

The partner feed originally arrived as plain CSV, and later grew gzip and
bz2 variants as volumes increased, so this module dispatches on suffix
instead of requiring a codec argument from callers. Writers use a fixed
compression level to keep output byte-for-byte reproducible, which the
nightly checksum comparison depends on. Streams are opened lazily and
must be closed by the caller.
"""
import bz2
import gzip

LEVEL = 6


def open_export(path, mode="rb"):
    if path.endswith(".gz"):
        if "w" in mode:
            return gzip.open(path, mode, compresslevel=LEVEL, mtime=0)
        return gzip.open(path, mode)
    if path.endswith(".bz2"):
        return bz2.open(path, mode, compresslevel=LEVEL)
    return open(path, mode)

