def load_stage_flags(env):
    """Return the set of stages named in STAGES_ENABLED.

    An empty or whitespace-only value yields an empty set, not the default
    stages, so an operator can disable everything. Unset means all defaults.
    """
    default = {"extract", "transform", "load"}
    raw = env.get("STAGES_ENABLED")
    if raw is None:
        return default
    names = {part.strip().lower() for part in raw.split(",")}
    names.discard("")
    unknown = names - default
    if unknown:
        raise ValueError("unknown stages: " + ", ".join(sorted(unknown)))
    return names

