class MissingAwareCache:
    """Memoizing wrapper that also remembers lookups returning None.

    A None result is cached like any other value, so a key that is added to
    the backing store later will keep returning None until clear() is called.
    The cache is unbounded and not thread-safe.
    """

    _UNSET = object()

    def __init__(self, fetch):
        self._fetch = fetch
        self._store = {}

    def lookup(self, key):
        found = self._store.get(key, self._UNSET)
        if found is self._UNSET:
            found = self._fetch(key)
            self._store[key] = found
        return found

    def clear(self):
        self._store.clear()

