class SchemaResolverCache:
    """Cache parsed schemas keyed by (subject, version).

    This replaced a module-level functools.lru_cache because that cache
    could not be cleared per tenant and kept stale schemas alive after the
    registry client was swapped out in tests. Each instance owns its own
    dict, so a registry client and its cache share one lifetime. Entries for
    the special version "latest" are never stored, since that alias moves
    when a new schema is registered.
    """

    def __init__(self, registry):
        self._registry = registry
        self._parsed = {}

    def resolve(self, subject, version):
        if version == "latest":
            return self._registry.fetch(subject, version)
        key = (subject, version)
        if key not in self._parsed:
            self._parsed[key] = self._registry.fetch(subject, version)
        return self._parsed[key]

