class RowKeyMemo:
    """Memoize derived row keys, evicting the oldest entry at capacity.

    Eviction is by insertion order, not by recent use, so a hot key can be
    dropped and recomputed. The key function must be pure: it is called
    again after eviction and the result is expected to be identical. Passing
    max_entries below 1 raises ValueError.
    """

    def __init__(self, key_fn, max_entries=1024):
        if max_entries < 1:
            raise ValueError("max_entries must be at least 1")
        self._key_fn = key_fn
        self._max = max_entries
        self._items = {}

    def key_for(self, row):
        ident = row["id"]
        if ident not in self._items:
            if len(self._items) >= self._max:
                self._items.pop(next(iter(self._items)))
            self._items[ident] = self._key_fn(row)
        return self._items[ident]

