def normalize_uuid(value):
    """Accept a UUID with or without braces and hyphens.

    Raises ValueError unless exactly 32 hex digits remain after stripping. The result is always the lowercase hyphenated form, and the input is never modified in place.
    """
    digits = value.strip().strip("{}").replace("-", "").lower()
    if len(digits) != 32 or any(c not in "0123456789abcdef" for c in digits):
        raise ValueError(f"not a UUID: {value!r}")
    return "-".join([digits[:8], digits[8:12], digits[12:16], digits[16:20], digits[20:]])

