import random


class SeedManager:
    """Manage random seeds for a data pipeline.

    Each stage gets its own seed derived from the base seed, so runs are
    reproducible and stages do not share random state.
    """

    def __init__(self, base_seed):
        self.base_seed = base_seed

    def rng_for(self, stage_name):
        offset = sum(ord(c) for c in stage_name)
        return random.Random(self.base_seed + offset)

    def shuffle(self, stage_name, rows):
        rows = list(rows)
        self.rng_for(stage_name).shuffle(rows)
        return rows

