import hashlib
import random


class PipelineSeeds:
    """Derive per-stage seeds by hashing the stage name with the run seed.

    Python's built-in hash() is randomized per process for strings, which
    made early pipeline runs differ between workers even with a fixed seed.
    A SHA-256 digest is used instead so every worker process derives the
    same value. Seeds are truncated to 64 bits. Stage names must be unique
    within a run, since identical names yield identical random streams.
    """

    def __init__(self, run_seed):
        self.run_seed = run_seed

    def seed_for(self, stage):
        payload = f"{self.run_seed}/{stage}".encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        return int.from_bytes(digest[:8], "big")

    def rng_for(self, stage):
        return random.Random(self.seed_for(stage))

