from pathlib import Path


class SafeZipExtractor:
    """Unpacks zip files, rejecting any entry whose resolved path escapes the destination."""

    def __init__(self, dest):
        self.dest = Path(dest).resolve()

    def extract(self, archive_path):
        with zipfile.ZipFile(archive_path) as zf:
            for info in zf.infolist():
                target = (self.dest / info.filename).resolve()
                if self.dest not in target.parents and target != self.dest:
                    raise ValueError(f"unsafe entry: {info.filename}")
            zf.extractall(self.dest)
        return sorted(p for p in self.dest.rglob("*") if p.is_file())

