class BoundedZipReader:

    def __init__(self, dest, max_bytes=500_000_000):
        self.dest = Path(dest)
        self.max_bytes = max_bytes

    def extract(self, archive_path):
        with zipfile.ZipFile(archive_path) as zf:
            declared = sum(i.file_size for i in zf.infolist())
            if declared > self.max_bytes:
                raise ValueError(f"archive declares {declared} bytes")
