class ColumnDefaults(dict):
    """Per-column fallback values applied while normalizing rows.

    Earlier versions used collections.defaultdict, but its factory inserted
    every missing key on read, which leaked placeholder columns into the
    exported CSV header. This subclass resolves misses through __missing__
    against a frozen copy of the defaults, leaving the stored data untouched.
    The defaults are copied at construction, so later changes to the source
    dict do not affect existing instances.
    """

    def __init__(self, defaults, row=None):
        super().__init__(row or {})
        self._defaults = dict(defaults)

    def __missing__(self, column):
        return self._defaults[column]

    def fill(self):
        return {**self._defaults, **self}

