def purge_stale_entries(cache, max_age_seconds, now=None):
    """Remove entries older than max_age_seconds from the cache and return the number removed."""
    current = time.monotonic() if now is None else now
    stale = [
        key
        for key, (stored_at, _value) in cache.items()
        if current - stored_at > max_age_seconds
    ]
    for key in stale:
        del cache[key]
    return len(stale)

