"""Retry helpers for flaky network calls in dev scripts.

Delays are capped at 30 seconds and jittered, so total wait time is not
deterministic. Only exceptions listed in RETRYABLE are retried.
"""
import random
import time

RETRYABLE = (ConnectionError, TimeoutError)


def call_with_retry(fn, attempts=5, base=0.5):
    for n in range(attempts):
        try:
            return fn()
        except RETRYABLE:
            if n == attempts - 1:
                raise
            time.sleep(min(30, base * 2 ** n) * random.uniform(0.5, 1.0))

