"""Retry decorator that never retries non-idempotent calls by default.

Functions must opt in with idempotent=True, because a timeout does not prove
the request failed on the server. The final exception is re-raised unchanged
so its traceback still points at the original failure.
"""
import functools
import time


def retry(idempotent=False, tries=3, delay=1.0):
    def wrap(fn):
        @functools.wraps(fn)
        def inner(*args, **kwargs):
            limit = tries if idempotent else 1
            for n in range(limit):
                try:
                    return fn(*args, **kwargs)
                except OSError:
                    if n == limit - 1:
                        raise
                    time.sleep(delay * 2 ** n)
        return inner
    return wrap

