import threading


class ProgressCounter:
    """Thread-safe counter for progress output.

    Reads via value are not synchronized with increments, so a reader may see
    a count that is one step behind. Call finish() to get an exact total; it
    takes the lock and is meant for the final summary line only.
    """

    def __init__(self):
        self._lock = threading.Lock()
        self._count = 0

    @property
    def value(self):
        return self._count

    def bump(self, amount=1):
        with self._lock:
            self._count += amount

    def finish(self):
        with self._lock:
            return self._count

