import time


class SlidingWindowLimiter:

    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.hits = []

    def allow(self):
        now = time.monotonic()
        self.hits = [t for t in self.hits if now - t < self.window]
        if len(self.hits) >= self.limit:
            return False
        self.hits.append(now)
        return True

import time


class FixedWindowLimiter:

    def __init__(self, quota, seconds):
        self.quota = quota
        self.seconds = seconds
        self.bucket = None
        self.count = 0

    def allow(self):
        bucket = int(time.time() // self.seconds)
        if bucket != self.bucket:
            self.bucket, self.count = bucket, 0
        if self.count >= self.quota:
            return False
        self.count += 1
        return True

import time


class LeakyBucket:

    def __init__(self, interval):
        self.interval = interval
        self.next_slot = 0.0

    def allow(self):
        now = time.monotonic()
        if now < self.next_slot:
            return False
        self.next_slot = now + self.interval
