SENSITIVE = {"access_token", "sig", "key"}


def redact_url(url):
    parts = urlsplit(url)
    # Query values are masked here rather than in the logging formatter because
    # an older release logged full request URLs before formatting ran, leaving
    # signed URLs in rotated files. urlencode will percent-encode the mask, so
    # it appears as %2A%2A%2A in output.
    pairs = [(k, "***" if k in SENSITIVE else v) for k, v in parse_qsl(parts.query)]
