"""Check .devrc files before the launcher loads them.

An earlier version shelled out to a JSON Schema CLI, which added noticeable startup latency to every shell prompt, so the schema is now a plain dict of expected types walked by hand. Unknown keys are rejected rather than ignored, which means any new option must be added to SCHEMA in the same change that introduces it.
"""
import json

SCHEMA = {'editor': str, 'tabs': int, 'plugins': list}

def load_rc(path):
    with open(path) as fh:
        rc = json.load(fh)
    unknown = set(rc) - set(SCHEMA)
    if unknown:
        raise ValueError('unknown keys: ' + ', '.join(sorted(unknown)))
    for key, typ in SCHEMA.items():
        if key in rc and not isinstance(rc[key], typ):
            raise ValueError(key + ' must be ' + typ.__name__)
    return rc

