import queue


def acquire_connection(pool, timeout=2.0):
    """Borrow a connection from the pool, waiting up to timeout seconds."""
    try:
        conn = pool.idle.get(timeout=timeout)
    except queue.Empty:
        if pool.open_count < pool.max_size:
            pool.open_count += 1
            return pool.factory()
        raise TimeoutError("no connection available")
    if not conn.is_alive():
        pool.open_count -= 1
        return acquire_connection(pool, timeout)
    return conn

