class FrameReader:

    def __init__(self):
        self._buf = bytearray()

    def feed(self, chunk):
        self._buf.extend(chunk)
        frames = []
        while len(self._buf) >= 4:
            (size,) = struct.unpack_from(">I", self._buf)
            if len(self._buf) < 4 + size:
                break
            frames.append(bytes(self._buf[4:4 + size]))
            del self._buf[:4 + size]
        return frames

