class EnvReader:
    """Typed reader over a snapshot of os.environ.

    The mapping is copied at construction, so later changes to os.environ
    are not seen by an existing reader. Boolean parsing accepts only
    1/0/true/false/yes/no (case-insensitive); anything else raises
    ValueError rather than being treated as False.
    """

    _TRUE = {"1", "true", "yes"}
    _FALSE = {"0", "false", "no"}

    def __init__(self, environ):
        self._env = dict(environ)

    def get_bool(self, name, default=False):
        raw = self._env.get(name)
        if raw is None:
            return default
        value = raw.strip().lower()
        if value in self._TRUE:
            return True
        if value in self._FALSE:
            return False
        raise ValueError(f"{name} is not a boolean: {raw!r}")

