class ShellEnvSnapshot:

    def __init__(self, shell="/bin/sh"):
        self.shell = shell
        self._cache = None

    def refresh(self):
        import subprocess
        proc = subprocess.run(
            [self.shell, "-lc", "env -0"], capture_output=True, timeout=10
        )
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr.decode(errors="replace"))
        pairs = proc.stdout.decode().split("\0")
        self._cache = dict(p.split("=", 1) for p in pairs if "=" in p)
        return self._cache

