class PrefixedSettings:
    """Exposes variables sharing a prefix as a lowercase-keyed mapping.

    The prefix is stripped and keys are lowercased, so APP_DB_HOST becomes
    "db_host". If two variables collide after lowercasing (APP_Port and
    APP_PORT), the lexicographically later original name wins, which makes
    results deterministic but is easy to miss. Values are never coerced and
    remain strings.
    """

    def __init__(self, environ, prefix="APP_"):
        self.prefix = prefix
        self._data = {}
        for name in sorted(environ):
            if name.startswith(prefix):
                self._data[name[len(prefix):].lower()] = environ[name]

    def __getitem__(self, key):
        return self._data[key]

    def as_dict(self):
        return dict(self._data)

