"""Small TTL memoizer; entries expire after a fixed number of seconds."""

import time


def ttl_cache(seconds):
    def decorator(func):
        store = {}

        def wrapper(*args):
            now = time.monotonic()
            hit = store.get(args)
            if hit and now - hit[0] < seconds:
                return hit[1]
            value = func(*args)
            store[args] = (now, value)
            return value

        return wrapper

    return decorator

