from collections import OrderedDict


def lru_memo(func, limit=128):
    store = OrderedDict()

    def wrapper(key):
        if key in store:
            store.move_to_end(key)
            return store[key]
        value = func(key)
        store[key] = value
        if len(store) > limit:
            store.popitem(last=False)
        return value

    return wrapper

