from datetime import datetime, timezone


def encode_event(event):
    def default(obj):
        if isinstance(obj, datetime):
            return obj.astimezone(timezone.utc).isoformat()
        raise TypeError(type(obj).__name__)
    return json.dumps(event, default=default)


def test_encode_event_normalizes_datetime_to_utc():
    """Regression guard for naive local offsets leaking into stored events.

    The encoder historically wrote datetimes with whatever offset the caller
    supplied, which made diffs between machines in different zones noisy. The
    encoder now converts to UTC before formatting, and this test pins that
    by passing a +05:00 timestamp and expecting a +00:00 result.
    """
    from datetime import timedelta
    tz = timezone(timedelta(hours=5))
    out = encode_event({"at": datetime(2024, 3, 1, 15, 0, tzinfo=tz)})
    assert json.loads(out)["at"] == "2024-03-01T10:00:00+00:00"

