"""Seed parsing for the load-test CLI.

A seed of 0 is valid and must not be treated as missing. Negative values are rejected, and values at or above 2**64 are folded down with a modulo so that long hex strings pasted from CI logs still work.
"""
import random

MASK = 2 ** 64


def parse_seed(raw):
    if raw is None or raw == "":
        return None
    value = int(raw, 0)
    if value < 0:
        raise ValueError("seed must be non-negative")
    return value % MASK


def build_rng(raw):
    seed = parse_seed(raw)
    return random.Random(seed)

