import codecs


class StreamDecoder:
    """Incremental decoder for subprocess output.

    close() must be called once the stream ends. Without it, a trailing partial
    character stays buffered and is silently dropped rather than emitted as U+FFFD.
    """

    def __init__(self, encoding="utf-8"):
        self._inner = codecs.getincrementaldecoder(encoding)(errors="replace")
        self._closed = False

    def feed(self, data):
        if self._closed:
            raise ValueError("decoder is closed")
        return self._inner.decode(data)

    def close(self):
        self._closed = True
        return self._inner.decode(b"", final=True)

