import codecs


class TailDecoder:
    """Incremental decoder used by the live tail view.

    This wraps codecs.getincrementaldecoder rather than calling bytes.decode on each
    read, which an earlier version did and which produced replacement characters
    whenever a pipe read ended inside a multibyte sequence. Decoder state is kept per
    instance, so a single instance must not be shared between streams. Invalid bytes
    are replaced, never raised, so the view keeps scrolling on corrupt input.
    """

    def __init__(self, encoding="utf-8"):
        self._decoder = codecs.getincrementaldecoder(encoding)(errors="replace")

    def feed(self, data):
        return self._decoder.decode(data)

    def flush(self):
        return self._decoder.decode(b"", final=True)

