import subprocess


def capture_version(binary):
    proc = subprocess.Popen([binary, "--version"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    try:
        out, _ = proc.communicate(timeout=5)
        return out.decode("utf-8", "replace").strip()
    finally:
        # communicate() does not reap the child when it raises, so poll first;
        # kill() on an already-exited process is harmless but wait() is still required.
        if proc.poll() is None:
            proc.kill()
        proc.wait()

