import signal
import subprocess


def stop_server(proc, grace=3.0):
    if proc.poll() is not None:
        return proc.returncode
    proc.send_signal(signal.SIGTERM)
    try:
        return proc.wait(timeout=grace)
    except subprocess.TimeoutExpired:
        # The dev server traps SIGTERM while a reload is in flight, so a
        # timeout here is expected on busy trees. Escalate to SIGKILL; the
        # lock file in .devserver/ is cleared on next start, not here.
        proc.kill()
        return proc.wait()

