class DateRange:
    """An inclusive range of calendar dates.

    Both `start` and `end` are part of the range, so a range with equal
    endpoints has length one. Constructing one with end before start raises
    ValueError.
    """

    def __init__(self, start, end):
        if end < start:
            raise ValueError("end precedes start")
        self.start = start
        self.end = end

    def __len__(self):
        return (self.end - self.start).days + 1

    def __iter__(self):
        for offset in range(len(self)):
            yield self.start + timedelta(days=offset)

