import calendar
from datetime import date


class BillingPeriod:
    """A monthly billing window anchored to a day of the month.

    When the anchor day does not exist in a month, such as 31 in April,
    the period clamps to that month's last day instead of rolling into
    the next month.
    """

    def __init__(self, anchor_day):
        self.anchor_day = anchor_day

    def start_in(self, year, month):
        last = calendar.monthrange(year, month)[1]
        return date(year, month, min(self.anchor_day, last))

    def next_start(self, year, month):
        if month == 12:
            return self.start_in(year + 1, 1)
        return self.start_in(year, month + 1)

