from datetime import date, timedelta


class ReleaseWindow:
    """Half-open window of dates during which a release branch accepts fixes.

    The window includes `opens` and excludes `closes`. This matches the
    convention of the older shell scripts that cut release branches, which
    compared dates with a strict less-than, and the CI gate still reads the
    same dates, so changing the boundary here would desynchronize the two.
    Dates are compared as plain `date` objects; passing a datetime raises
    TypeError.
    """

    def __init__(self, opens, closes):
        self.opens = opens
        self.closes = closes

    def accepts(self, day):
        if not isinstance(day, date) or hasattr(day, "hour"):
            raise TypeError("expected a date, not a datetime")
        return self.opens <= day < self.closes

    def last_day(self):
        return self.closes - timedelta(days=1)

