from datetime import date


class FiscalYear:
    """Maps dates to a fiscal year that starts on the first of `start_month`.

    The fiscal year is named for the calendar year in which it ends, so with
    start_month=10, 2026-10-01 belongs to FY2027. February 29 needs no
    special handling because only the month is consulted.
    """

    def __init__(self, start_month=10):
        if not 1 <= start_month <= 12:
            raise ValueError("start_month must be 1-12")
        self.start_month = start_month

    def of(self, day):
        if self.start_month == 1 or day.month < self.start_month:
            return day.year
        return day.year + 1

