def mask_email(address):
    local, sep, domain = address.partition("@")
    if not sep:
        return address
    # The legacy log scrubber matches on the first and last character of the local
    # part, which is why those two survive masking; the log format predates this helper.
    if len(local) <= 2:
        masked = "*" * len(local)
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]
    return f"{masked}@{domain}"


def mask_many(addresses):
    return [mask_email(a) for a in addresses]

